function initMap(){var e=new google.maps.LatLng(51.447042,(-.127849)),n={zoom:14,center:e,mapTypeId:google.maps.MapTypeId.ROADMAP,disableDefaultUI:!0,animation:google.maps.Animation.DROP,scrollwheel:!1},o=new google.maps.Map(document.getElementById("map"),n),a="AT Medics Head Office,<br /> 26-28 Streatham Place<br />London, SW2 4QY",t=new google.maps.InfoWindow({content:a,maxWidth:500}),i=new google.maps.Marker({position:e,map:o,icon:"images/map/marker.png"});google.maps.event.addListener(i,"click",function(){t.open(o,i),o.setZoom(16)}),markers.push(i),google.maps.event.addDomListener(window,"resize",function(){var e=o.getCenter();google.maps.event.trigger(o,"resize"),o.setCenter(e)})}function myClick(e){google.maps.event.trigger(markers[e],"click")}var markers=[];$(document).ready(function(){var e=$("#map");e.length&&initMap()});